          "sampleSolution": "public class Employee {\n    private String name;\n    private int salary;\n\n    public Employee() {\n    }\n\n    public Employee(String name, int salary) {\n        this.name = name;\n        this.salary = salary;\n    }\n\n    public String getName() {\n        return name;\n    }\n\n    public int getSalary() {\n        return salary;\n    }\n\n    public void setName(String name) {\n        this.name = name;\n    }\n\n    @Override\n    public String toString() {\n        return name + \",\" + salary;\n    }\n}\n\npublic class Manager extends Employee {\n    private String department;\n\n    public Manager() {\n    }\n\n    public Manager(String name, int salary, String department) {\n        super(name, salary);\n        this.department = department;\n    }\n\n    @Override\n    public String toString() {\n        return super.toString() + \",\" + department;\n    }\n\n    // Hypothesis (missing spec page): replace the 3rd character of name with \"KK\".\n    public void setData() {\n        String name = getName();\n        if (name.length() >= 3) {\n            setName(name.substring(0, 2) + \"KK\" + name.substring(3));\n        }\n    }\n\n    public int getValue() {\n        if (department.equals(\"it\")) {\n            return getSalary() + 200;\n        }\n        return getSalary() + 900;\n    }\n}",
